package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.time.Duration;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FlashDesignTest {
 Application app;ServiceController<QuickSearchService> driver;QuickSearchService service;
 @Before public void before()throws Exception{app=RuntimeEnvironment.getApplication();app.getSharedPreferences("seeky",0).edit().putBoolean("motion",false).putBoolean("monitor_enabled",false).putString("theme","Claro").apply();QuickSearchService.overlayOwners.clear();java.lang.reflect.Method add=android.content.res.AssetManager.class.getDeclaredMethod("addAssetPath",String.class);add.setAccessible(true);add.invoke(app.getAssets(),System.getProperty("seeky.main.resources"));
 // Config.NONE has no application package resource table. Load the unchanged production
 // wordmark into the same cache, so screenshots use the actual packaged brand asset.
 try(java.util.zip.ZipFile resources=new java.util.zip.ZipFile(System.getProperty("seeky.main.resources"));InputStream in=resources.getInputStream(resources.getEntry("res/drawable/wordmark.webp"))){BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=4;opts.inScaled=false;java.lang.reflect.Field logo=AppImages.class.getDeclaredField("logo");logo.setAccessible(true);logo.set(null,AppImages.visible(BitmapFactory.decodeStream(in,null,opts)));}}

 @After public void after(){if(driver!=null)driver.destroy();QuickSearchService.overlayOwners.clear();}
 void service(){driver=Robolectric.buildService(QuickSearchService.class).create();service=driver.get();}
 Catalog.Entry entry(String name,String category){Catalog.Entry e=new Catalog.Entry();e.name=name;e.category=category;e.path="Livros / Formação pessoal";e.uri="content://flash.fixture/"+name;e.size=234567;e.mime=MediaFormats.mime(name,null);return e;}
 void layout(View v,int w,int h){v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);}
 void image(View v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+name+".png")){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}b.recycle();}
 FlashPanelView view(String theme){app.getSharedPreferences("seeky",0).edit().putString("theme",theme).apply();return new FlashPanelView(app,new FlashPanelView.Actions(){public void close(){}public void open(){}public void stop(){}public void mode(boolean f){}public void folders(){}public void category(String c){}});}
 @Test public void actualSearchPanelHasReadableRowsSeparatedControlsAndSelectedFiltersInBothThemes()throws Exception{
  for(String theme:new String[]{"Claro","Escuro","Âmbar"}){FlashPanelView p=view(theme);p.input.setText("organização");p.status.setText("3 resultados");p.setCategory("Documentos");for(String name:new String[]{"Organização e planeamento.pdf","Método de estudo.epub","Gestão do tempo.docx"}){FileRowView row=new FileRowView(app,(e,v)->{});row.bind(entry(name,"Documentos"),p.palette.tint,p.palette.ink,p.palette.muted,p.palette.accent,true,"");row.star.setVisibility(View.GONE);row.arrow.setVisibility(View.VISIBLE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=8;p.results.addView(row,lp);}layout(p,360,600);assertTrue(p.scroll.getHeight()>=150);assertTrue(p.folders.getLeft()-((View)p.flash.getParent()).getRight()>=8);assertTrue(p.chips.get("Documentos").isSelected());assertFalse(p.chips.get("Tudo").isSelected());assertEquals(View.VISIBLE,p.clear.getVisibility());image(p,"-flash-"+theme);p.clear.performClick();assertEquals("",p.input.getText().toString());assertEquals(View.GONE,p.clear.getVisibility());}
 }
 @Test public void compactKeyboardLayoutLeavesRoomForResultsAndAllSearchModes()throws Exception{FlashPanelView p=view("Escuro");p.compact(true);layout(p,288,310);assertTrue(p.scroll.getHeight()>=60);assertEquals(View.GONE,p.categories.getVisibility());assertEquals(View.GONE,p.footer.getVisibility());assertEquals(View.VISIBLE,p.flash.getVisibility());assertEquals(View.VISIBLE,p.complete.getVisibility());assertEquals(View.VISIBLE,p.folders.getVisibility());assertTrue(p.folders.getRight()<=288-16);image(p,"-flash-keyboard");}
 @Test public void floatingButtonHasCircularVisualAndGenerousHitAreaAndCanBeDragged()throws Exception{
  service();service.bubble();assertTrue(service.window instanceof FlashBubbleView);assertEquals(60,service.params.width);layout(service.window,60,60);FlashBubbleView bubble=(FlashBubbleView)service.window;assertEquals(52,bubble.circle.getWidth());assertEquals(52,bubble.circle.getHeight());image(bubble,"-flash-bubble");int x=service.params.x,y=service.params.y;long now=SystemClock.uptimeMillis();bubble.dispatchTouchEvent(MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,30,30,0));bubble.dispatchTouchEvent(MotionEvent.obtain(now,now+20,MotionEvent.ACTION_MOVE,120,90,0));bubble.dispatchTouchEvent(MotionEvent.obtain(now,now+40,MotionEvent.ACTION_UP,120,90,0));assertTrue(service.params.x>=6);assertTrue(service.params.x+service.params.width<=354);assertTrue(service.params.y>=y);assertTrue(app.getSharedPreferences("seeky",0).contains("float_x"));assertFalse(service.expanded);
 }
 @Test public void panelModeSwitchesPersistAndOutsideTapCollapsesWithoutStoppingSearchService(){service();service.bubble();service.expand();assertTrue(service.expanded);FlashPanelView p=service.panelView;p.complete.performClick();assertFalse(service.prefs.getBoolean("flash_mode",true));assertTrue(p.complete.isSelected());p.flash.performClick();assertTrue(service.prefs.getBoolean("flash_mode",false));p.chips.get("PDF").performClick();assertEquals("PDF",service.quickCategory);assertTrue(p.chips.get("PDF").isSelected());p.dispatchTouchEvent(MotionEvent.obtain(0,1,MotionEvent.ACTION_OUTSIDE,-1,-1,0));assertFalse(service.expanded);assertTrue(service.window instanceof FlashBubbleView);assertFalse(service.dead);}
 @Test public void staleSearchResultsCannotOverwriteTheCurrentQuery(){service();service.bubble();service.expand();service.input.setText("novo");int old=service.serial;service.input.setText("actual");Map<String,Catalog.Entry> result=new LinkedHashMap<>();Catalog.Entry e=entry("Texto antigo.pdf","PDF");result.put(e.uri,e);service.publish(old,result,"Flash · 1 · 3 ms");shadowOf(Looper.getMainLooper()).idle();assertEquals(0,service.results.getChildCount());service.publish(service.serial,result,"Flash · 1 · 3 ms");shadowOf(Looper.getMainLooper()).idle();assertEquals(1,service.results.getChildCount());assertEquals("1 resultado",service.status.getText().toString());assertFalse(service.status.getText().toString().contains("ms"));}
 @Test public void imeInsetsResizeThePanelInsideAvailableScreen(){service();service.bubble();service.expand();FlashPanelView p=service.panelView;WindowInsets insets=new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),Insets.of(0,24,0,24)).setInsets(WindowInsets.Type.ime(),Insets.of(0,0,0,400)).setVisible(WindowInsets.Type.ime(),true).build();p.dispatchApplyWindowInsets(insets);assertTrue(service.params.y+service.params.height<=800-400-12);assertEquals(View.GONE,p.categories.getVisibility());assertEquals(View.GONE,p.footer.getVisibility());}
 @Test public void wordmarkKeepsReadableVisibleBoundsAndDarkThemeContrast()throws Exception{java.lang.reflect.Field cache=AppImages.class.getDeclaredField("logo");cache.setAccessible(true);Bitmap logo=(Bitmap)cache.get(null);assertTrue(logo.getWidth()>logo.getHeight()*1.8f);assertTrue(logo.getWidth()<500);app.getSharedPreferences("seeky",0).edit().putString("theme","Escuro").apply();ImageView brand=new ImageView(app);AppImages.wordmark(brand);assertNotNull(brand.getColorFilter());app.getSharedPreferences("seeky",0).edit().putString("theme","Claro").apply();AppImages.wordmark(brand);assertNull(brand.getColorFilter());}
 @Test public void changingThemeRepaintsAnExistingBubble(){service();service.bubble();View old=service.window;service.prefs.edit().putString("theme","Escuro").apply();shadowOf(Looper.getMainLooper()).idle();assertNotSame(old,service.window);FlashBubbleView bubble=(FlashBubbleView)service.window;assertEquals(AppPalette.of(app).onAccent,((Icons)bubble.circle.getChildAt(0)).color);}
 @Test public void androidGoFallbackUsesTheSameControlsAndFoldersOpenTheExplorer(){ActivityController<FlashSearchActivity> c=Robolectric.buildActivity(FlashSearchActivity.class).setup();try{FlashSearchActivity a=c.get();assertNotNull(a.panel);a.panel.complete.performClick();assertFalse(a.getSharedPreferences("seeky",0).getBoolean("flash_mode",true));a.panel.folders.performClick();Intent i=shadowOf(a).getNextStartedActivity();assertTrue(i.getBooleanExtra("open_explorer",false));assertTrue(a.isFinishing());}finally{c.pause().stop().destroy();}}
}
